// Частотный счётчик: O(n) вместо O(n²)
function hasPairWithSum(nums, target) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(target - n)) return true; // ищем дополнение за O(1)
    seen.add(n);
  }
  return false;
}

type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: Order[] }
  | { status: 'error'; message: string };

function OrdersView({ state }: { state: State }) {
  switch (state.status) {
    case 'loading':   return <Spinner />;
    case 'success':   return <OrderList items={state.data} />; // data виден только в этой ветке
    case 'error':     return <ErrorBox text={state.message} />;
    default:          return <Empty />;
  }
}

